"""Jacksonville experiment pages; called by the existing core-page generator."""
from html import escape
from site_components import ROOT, head, header, footer, compact_credentials

ROUTES = {"JAX_PHC": "jacksonville-palm-health.html", "JAX_SOURCING": "jacksonville-mature-palm-sourcing.html"}
CITIES = ["Jacksonville", "Jacksonville Beach", "Atlantic Beach", "Neptune Beach", "Ponte Vedra Beach", "Nocatee", "St. Johns"]

def field(name, label, kind="text", required=False, options=None):
    attrs = f'name="{name}" id="jax-{name}"' + (' required' if required else '')
    if options:
        control = f'<select {attrs}><option value="">Choose…</option>' + ''.join(f'<option>{escape(o)}</option>' for o in options) + '</select>'
    elif kind == "textarea":
        control = f'<textarea {attrs} rows="3" maxlength="3000"></textarea>'
    else:
        extra = ' min="1" max="10000" step="1"' if kind == "number" else ' maxlength="200"'
        if name == 'zip': extra += ' inputmode="numeric" pattern="[0-9]{5}"'
        control = f'<input type="{kind}" {attrs}{extra}>'
    return f'<label for="jax-{name}">{escape(label)}{(" *" if required else "")}{control}</label>'

def questions(items):
    return ''.join(field(n, l, options=["Yes", "No", "Not sure"]) for n,l in items)

def form(campaign):
    phc = campaign == 'JAX_PHC'
    common = field('name','Name',required=True) + field('email','Email','email',True) + field('phone','Phone','tel',True) + field('zip','Project ZIP code',required=True)
    common += field('city','Property / project city',required=True,options=CITIES + ['Other — describe in notes'])
    common += field('customer_type','I am a…',required=True,options=['Homeowner','HOA','Property manager','Landscape contractor','Tree company','Landscape architect','Developer / builder','Nursery / installer','Hotel / resort','Commercial owner','Other'])
    common += field('species','Palm species, if known')
    if phc:
        common += field('issue_category','What are you seeing?',required=True,options=['Unknown decline','Lethal bronzing concern','Weevil / pest concern','Nutrition','Transplant stress','Freeze injury','Crown decline','Preventive protection','Other'])
        common += field('problem','Tell me what changed','textarea',True)
        advanced = field('quantity','Affected palm count','number') + field('size','Approximate palm size / overall height') + field('clear_trunk_ft','Approximate clear-trunk height (feet)') + field('symptom_duration','How long have symptoms been present?')
        advanced += '<fieldset data-issue="Lethal bronzing concern|Unknown decline"><legend>Fruit, flowers and fronds</legend><div class="jax-grid">' + questions([('fruit_drop','Recent premature fruit drop?'),('black_flowers','Blackened / abnormal flower stalks?'),('lower_bronzing','Lower fronds bronzing or dying?')]) + '</div></fieldset>'
        advanced += '<fieldset data-issue="Weevil / pest concern|Crown decline|Unknown decline"><legend>Crown and insects</legend><div class="jax-grid">' + questions([('spear_affected','Newest leaf / spear affected?'),('crown_collapse','Crown collapsing?'),('visible_insects','Visible insects / beetles?')]) + '</div></fieldset>'
        advanced += '<fieldset><legend>Recent changes</legend><div class="jax-grid">' + questions([('transplanted','Recently transplanted?'),('freeze_exposure','Recent freeze / cold exposure?'),('pruning','Recent pruning?'),('irrigation_changes','Irrigation changes?'),('construction','Nearby construction / root damage?'),('storm_damage','Recent storm damage?')]) + '</div></fieldset>' + field('fertilizer','Fertilizer used, if known')
        common += '<details class="jax-advanced"><summary>Add palm history and symptoms (optional)</summary><div class="jax-grid">' + advanced + '</div></details>'
    else:
        common += field('quantity','Quantity needed','number',True) + field('clear_trunk_ft','Desired clear-trunk height (feet)',required=True) + field('overall_height','Desired overall height, if known')
        common += field('budget_range','Total project budget',required=True,options=['Under $5,000','$5,000–$15,000','$15,000–$30,000','$30,000–$75,000','$75,000+','Need guidance'])
        common += field('timeline','Desired project timing',required=True,options=['Within 30 days','1–3 months','3–6 months','6+ months','Exploring / no date'])
        common += '<details class="jax-advanced"><summary>Add delivery, installation and site requirements</summary><div class="jax-grid">' + field('company','Company') + field('project_location','Project location (no access codes)') + field('caliper','Trunk / caliper size, if relevant') + field('target_budget','Specific budget, if known') + field('delivery_scope','What do you need?',options=['Delivery only','Delivery and installation','Sourcing only','Not sure']) + questions([('installation_required','Installation required?'),('crane_available','Crane access available?'),('crane_required','Crane likely required?'),('alternatives','Alternative species acceptable?')]) + field('site_access','Site access / logistics notes','textarea') + '</div></details>'
    common += field('preferred_contact','Preferred contact',options=['Email','Phone call','Text message']) + field('notes','Additional notes','textarea')
    return f'''<section class="section section-tint" id="jax-inquiry"><div class="section-intro"><p class="eyebrow">Talk with John at SDPP</p><h2>{'Tell me what is happening with your palm.' if phc else 'Tell me the palm your project needs.'}</h2><p>{'Start with the basics. Photos help me decide what information or local assessment may be needed.' if phc else 'Species, clear-trunk height, budget and access help determine whether a search is practical.'} Availability, scope and any fee are confirmed before booking.</p></div>
<form class="jax-form" data-jax-form data-campaign="{campaign}" action="/api/jacksonville" method="post"><div class="jax-grid">{common}</div>
<label class="jax-upload">{'Palm photos: whole palm, crown and close-up' if phc else 'Site photos and examples of the palm you want'}<input type="file" name="photos" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple><small>Up to 3 photos. Phone images are resized before sending. If your phone image cannot be read, use JPEG or email the originals.</small></label><div data-photo-preview aria-live="polite"></div>
<label class="jax-honey" aria-hidden="true">Leave blank<input name="website" tabindex="-1" autocomplete="off"></label>
<label class="jax-consent"><input type="checkbox" name="contact_consent" required> I agree that San Diego Palm Protection LLC may contact me about this request. I have permission to share these photos. Please omit people, license plates and access codes.</label>
<p class="note">Your details and photos are delivered privately to SDPP through its inquiry provider to review and respond to this request. They are not posted publicly or sent to advertising analytics. Contact SDPP to request correction or deletion.</p>
<div data-jax-challenge></div><button class="button" type="submit" disabled>{'Request a Palm Assessment' if phc else 'Request a Palm Search'}</button><p role="status" data-jax-status>Checking secure delivery…</p>
<noscript><p>Secure photo submission requires JavaScript. Call or use the email link below; attach your photos in your email app.</p></noscript>
<a href="mailto:sandiegopalmprotection@gmail.com?subject={campaign}%20inquiry">Email SDPP instead</a> · <a data-jax-call href="tel:2624923135">Call or text 262-492-3135</a><p class="note">Opening your email app does not send a request. Send it from your email app.</p></form></section>'''

def render():
    for campaign, route in ROUTES.items():
        phc = campaign == 'JAX_PHC'
        title = 'Palm Health & Protection — Jacksonville Area | SDPP' if phc else 'Mature Palm Sourcing — Jacksonville Area | SDPP'
        h1 = 'Is your palm declining?' if phc else 'Looking for a mature date palm?'
        lede = 'Send me photos and tell me what changed. I’ll help you work out the next step for a valuable palm in Jacksonville or Northeast Florida.' if phc else 'Tell me the species, size and project location. I help locate hard-to-find specimen palms and review the delivery and installation requirements.'
        cta = 'Request a Palm Assessment' if phc else 'Request a Palm Search'
        if phc:
            body = '''<section class="section"><div class="section-intro"><p class="eyebrow">Palm health &amp; protection · Jacksonville area</p><h2>Look at the problem before choosing a treatment.</h2><p>Yellow leaves, a failing spear and crown decline can have different causes. A photo review can help identify the next question; it cannot confirm a disease or replace an inspection or laboratory test.</p></div><div class="service-lines service-lines--3">
<article><h3>Bronzing and sudden decline</h3><p>Early fruit drop, abnormal flower stalks and lower-frond bronzing warrant attention. Lethal bronzing affects susceptible date, sabal, queen and pindo palms. Similar symptoms can have other causes; testing may be needed. Symptomatic infected palms are not presented as curable.</p></article>
<article><h3>Crown and weevil concerns</h3><p>Tell me about spear damage, crown collapse or beetles, especially after transplanting, injury or stress. Florida’s native palmetto weevil, <i>Rhynchophorus cruentatus</i>, is one possibility in a broader health assessment.</p></article>
<article><h3>Yellowing and poor growth</h3><p>Potassium, magnesium, manganese and boron disorders can affect different leaves in different ways. Fertilizer history, irrigation, sandy soil and root conditions help explain what a palm may need.</p></article></div></section>
<section class="section section-tint"><div class="section-intro"><p class="eyebrow">What happens next</p><h2>Some palms need care. Others need a different decision.</h2><p>I start with the photos and history. We can then discuss local inspection, diagnostic testing referral, monitoring, nutrition planning, or a locally authorized treatment partner where appropriate. Bud rot, Ganoderma butt rot, Fusarium-related decline, drainage problems and root injury may require a different response. Some palms are unlikely to recover.</p></div><p>For healthy, valuable palms, ask about preventive planning and recurring monitoring. Local service availability and regulated work are confirmed separately before any commitment.</p><details><summary>Was there recent freeze damage?</summary><p>Brown foliage does not by itself establish whether a palm is lost. Note the date of the cold event and changes in new growth. Cold injury can be followed by delayed decline or secondary problems. Send photos before deciding on extensive pruning or removal.</p></details><p class="note">If a crown is collapsing or a palm may fall, keep people clear and contact a local qualified tree professional. This inquiry is not an emergency response service.</p></section>'''
        else:
            body = '''<section class="section"><div class="section-intro"><p class="eyebrow">A search for your project</p><h2>The right specimen starts with the right requirements.</h2><p>For private estates, landscape contractors, designers, developers, HOAs and commercial properties. Describe a Canary Island date palm, Sylvester palm, other Phoenix palm or another specimen you are trying to find. Alternative species may make the project more practical.</p></div><div class="process"><div><h3>Define the palm</h3><p>Species, quantity, clear-trunk height, desired overall size, budget and timing. Clear trunk and overall height are different measurements.</p></div><div><h3>Check possible sources</h3><p>Availability, condition, suitability and price must be confirmed for each candidate. Possible sources may be in California or elsewhere. No palm shown or discussed is reserved inventory.</p></div><div><h3>Review the landed cost</h3><p>Purchase, digging and preparation, freight, permits or plant-entry requirements, crane access, installation and establishment care all affect feasibility. Local partners and their scope must be confirmed.</p></div></div></section><section class="section section-tint"><div class="section-intro"><p class="eyebrow">Before a quote</p><h2>Can the palm get to the planting site?</h2><p>Send a wide view of the installation area and describe road access, overhead lines, gates and crane space. Delivery or installation is not included unless a written quote says so. Plant suitability, inspection requirements, freight and contractor availability are reviewed before a transaction.</p></div><p>SDPP is offering sourcing and coordination inquiries, not advertising a Jacksonville nursery or confirmed local inventory. A search request does not guarantee availability, transplant success or an installation date.</p></section>'''
        other = ROUTES['JAX_SOURCING' if phc else 'JAX_PHC']
        nav = header().replace('./palm-records-monitoring-verification.html#homeowner-inquiry', '#jax-inquiry').replace('Request Assessment</a>', cta + '</a>')
        foot = footer().replace('Owner-led South American palm weevil prevention, licensed treatment, and continuing care in San Diego County.', 'San Diego Palm Protection LLC · Jacksonville-area inquiries. Based in California; local availability is confirmed for each request.').replace('./palm-records-monitoring-verification.html#organization-inquiry', '#jax-inquiry').replace('Discuss Your Palms</a>', cta + '</a>')
        image = 'mature-cidp-old-escondido-san-diego-palm-protection.jpg' if phc else 'mansion_healthy_cidp_poway_three.jpg'
        text = f'''<!doctype html><html lang="en"><head>{head(title, lede, route, image)}<link rel="stylesheet" href="./site-assets/jacksonville.css"></head><body data-jax-campaign="{campaign}">{nav}<main id="main" class="site-main">
<section class="page-hero" style="--hero-image:url('/{image}')"><div class="hero-inner"><div class="hero-copy"><p class="eyebrow">San Diego Palm Protection · Northeast Florida inquiries</p><h1>{h1}</h1><p class="lede">{lede}</p><div class="button-row"><a class="button" href="#jax-inquiry">{cta}</a><a class="button button-quiet" data-jax-call href="tel:2624923135">Call or Text</a></div></div></div></section>
<div class="trust-wrap"><p class="note">Photograph: SDPP’s San Diego County field work; not Jacksonville inventory or a Florida service visit.</p><p><strong>Jacksonville-area market test by San Diego Palm Protection LLC.</strong> I’m John Krause, based in California. Florida treatment authority and local operating arrangements have not been established for this test. Any Florida pesticide work requires confirmed local authority, a suitable product and an agreed scope.</p><details><summary>SDPP’s California credentials</summary>{compact_credentials('BUSINESS_CREDENTIALS')}<p>These are California credentials and do not establish Florida authority.</p></details></div>{body}{form(campaign)}
<section class="section"><p class="eyebrow">Initial inquiry area</p><h2>Jacksonville and nearby coastal communities.</h2><p>{' · '.join(CITIES)}</p><p>Send the project ZIP code so I can confirm whether the request is serviceable.</p><p><a href="./{other}">{'Need a mature palm instead? Request sourcing help.' if phc else 'Concerned about an existing palm? Request a health review.'}</a></p>{('<p class="note">Palm-health references: <a href="https://ask.ifas.ufl.edu/publication/PP163">UF/IFAS lethal bronzing</a>, <a href="https://ask.ifas.ufl.edu/publication/IN139">palmetto weevil</a>, <a href="https://ask.ifas.ufl.edu/publication/EP273">nutrient deficiencies</a>.</p>' if phc else '')}</section></main>{foot}<script src="./site-assets/jacksonville.js" defer></script></body></html>'''
        (ROOT / route).write_text(text, encoding='utf-8')
    return list(ROUTES.values())
